import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth, createWorkspace, uniqueName } from './helpers';

test.describe(`household member: browse and search all vault entries`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
    await createWorkspace(page);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`the vault view always shows every current entry, filterable by service name`, async ({ page }) => {
    const nameA = uniqueName('netflix');
    const nameB = uniqueName('spotify');

    await page.getByTestId('field-service_name').fill(nameA);
    await page.getByTestId('field-username').fill('family@home.com');
    await page.getByTestId('field-secret').fill('s3cr3t!');
    await page.getByTestId('action-add_entry').click();
    await expect(
      page.locator('[data-testid^="item-vaultentry-"]').filter({ hasText: nameA }),
    ).toBeVisible({ timeout: 10_000 });

    await page.getByTestId('field-service_name').fill(nameB);
    await page.getByTestId('field-username').fill('family@home.com');
    await page.getByTestId('field-secret').fill('p4ssw0rd!');
    await page.getByTestId('action-add_entry').click();
    await expect(
      page.locator('[data-testid^="item-vaultentry-"]').filter({ hasText: nameB }),
    ).toBeVisible({ timeout: 10_000 });

    // The view shows every current entry (both are visible, unfiltered).
    await expect(
      page.locator('[data-testid^="item-vaultentry-"]').filter({ hasText: nameA }),
    ).toBeVisible();
    await expect(
      page.locator('[data-testid^="item-vaultentry-"]').filter({ hasText: nameB }),
    ).toBeVisible();

    // Filtering by service name narrows the list to matching entries only.
    await page.getByTestId('field-search').fill(nameA);
    await expect(
      page.locator('[data-testid^="item-vaultentry-"]').filter({ hasText: nameA }),
    ).toBeVisible();
    await expect(
      page.locator('[data-testid^="item-vaultentry-"]').filter({ hasText: nameB }),
    ).toBeHidden();
  });
});
